def decrypt(encrypted_text, n):
    if encrypted_text == '' or encrypted_text is None or n <= 0:
        return encrypted_text
    for _ in range(n):
        half = len(encrypted_text) // 2
        even_chars = encrypted_text[:half]
        odd_chars = encrypted_text[half:]
        decrypted_text = ''
        for i in range(len(encrypted_text)):
            if i % 2 == 0:
                decrypted_text += odd_chars[i // 2]
            else:
                decrypted_text += even_chars[i // 2]
        encrypted_text = decrypted_text
    return encrypted_text
